#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int a[5] = {5, 4, 3, 2, 1}, b[5] = {5, 4, 3, 2, 1};
    int n = 5, sw1 = 0, sw2 = 0;
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - 1 - i; j++)
            if (a[j] > a[j + 1]) { swap(a[j], a[j + 1]); sw1++; }
    for (int i = 0; i < n - 1; i++) {
        int m = i;
        for (int j = i + 1; j < n; j++) if (b[j] < b[m]) m = j;
        if (m != i) { swap(b[i], b[m]); sw2++; }
    }
    cout << sw1 << ' ' << sw2 << endl;
    return 0;
}

