#include <iostream>
using namespace std;

int ucln(int a, int b) {
    while (b != 0) { int r = a % b; a = b; b = r; }
    return a;
}

int bcnn(int a, int b) {
    return a / ucln(a, b) * b;
}

int main() {
    int a[3] = {4, 6, 10};
    int kq = a[0];
    for (int i = 1; i < 3; i++) {
        kq = bcnn(kq, a[i]);
        cout << kq << ' ';
    }
    cout << endl;
    return 0;
}

